using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasIndex(p => p.Sku);

            // BREAKING CHANGE 1 — Discriminator property renamed
            // EF Core 9 writes "$type" instead of "Discriminator".
            // Existing 500K docs use "Discriminator", and direct SQL
            // queries reference c.Discriminator. Keep the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — id format simplified
            // EF Core 8: id = "Product|123"
            // EF Core 9: id = "123"
            // Existing docs use the old format. Map the CosmosId shadow
            // property so lookups resolve to "Product|{Id}".
            entity.Property<string>("__id")
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyIdGenerator>();
        });
    }
}

/// <summary>
/// Reproduces the EF Core 8 id format: "EntityTypeName|KeyValue".
/// </summary>
class LegacyIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(Microsoft.EntityFrameworkCore.ChangeTracking.EntityEntry entry)
    {
        var entityType = entry.Metadata.ShortName();
        var pk = entry.Property("Id").CurrentValue;
        return $"{entityType}|{pk}";
    }
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

